#!/usr/bin/env python3
"""Write tests/differential/cases/boundary.case: the boundary anchors (B), (L) and (W) at the
start of a signature, at its end and in its middle, against every byte value. Run with
--record by clamav.py to fill in libclamav's verdicts."""
import sys

out = ["# Boundary anchors (B), (L) and (W) against every byte value at the start of a signature,",
       "# at its end and in its middle. The ClamAV docs give them one line each; these tables pin",
       "# libclamav's behaviour down. Generated by tools/diff/gen_boundary.py.", ""]
for tag, name in (("B", "Word"), ("L", "Line"), ("W", "NonAlnum")):
    for side in ("before", "after", "middle"):
        out.append("case boundary-%s-%s" % (name.lower(), side))
        sig = {"before": "(%s)6576696c", "after": "6576696c(%s)", "middle": "6576(%s)696c"}[side] % tag
        out.append("ndb Diff.Boundary.%s.%s:0:*:%s" % (name, side.capitalize(), sig))
        for b in range(256):
            body = {"before": '"\\x%02x" "evil"', "after": '"evil" "\\x%02x"', "middle": '"ev" "\\x%02x" "il"'}[side] % b
            out.append("sample bin %s bin => ?" % body)
        out.append("")
open(sys.argv[1] if len(sys.argv) > 1 else "tests/differential/cases/boundary.case", "w").write("\n".join(out))
